{
  "decisions": [
    {
      "requirement_id": "KK-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gecikme süresinin doğrulanması için sisteme girdi verilerek harita üzerindeki görsel çıktı ve zamanlama gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-002",
      "methods": [
        "Test"
      ],
      "rationale": "Yük testi yapılarak 2.000 iz altında ekran yenileme hızının ölçülmesi ve gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-003",
      "methods": [
        "Test"
      ],
      "rationale": "Operatörün iz seçimi işlemi gerçekleştirilerek ekranda doğru bilgilerin görüntülenip görüntülenmediği gözlemlenmelidir."
    },
    {
      "requirement_id": "KK-004",
      "methods": [
        "Test"
      ],
      "rationale": "Güncelleme akışının durdurulmasıyla zamanlama senaryosunun çalıştırılması ve iz durumundaki değişimlerin gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-005",
      "methods": [
        "Test"
      ],
      "rationale": "Tanımlı bölgeye iz girdiğinde görsel ve sesli uyarıların tetiklenip tetiklenmediği sistemin çalıştırılmasıyla doğrulanmalıdır."
    },
    {
      "requirement_id": "KK-006",
      "methods": [
        "Test"
      ],
      "rationale": "Mesaj gönderim işlemi yapılarak iletim süresinin ölçülmesi ve durum bildiriminin ekranda gözlemlenmesi gerekir."
    },
    {
      "requirement_id": "KK-007",
      "methods": [
        "Test"
      ],
      "rationale": "Operatör işlemleri gerçekleştirilerek log kayıtlarının zaman damgası ve kullanıcı kimliği ile doğru oluşturulup oluşturulmadığı kontrol edilmelidir."
    },
    {
      "requirement_id": "KK-008",
      "methods": [
        "Test"
      ],
      "rationale": "Birincil sunucunun arızalandırılması senaryosu çalıştırılarak yedek sunucunun devralma süresi ve veri bütünlüğü gözlemlenmelidir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "SW-001",
      "methods": [
        "Test"
      ],
      "rationale": "Gereksinim, belirli bir girdi (geçersiz belirteç) verildiğinde sistemin gözlemlenebilir davranışını (HTTP 401 yanıtı) tanımladığı için test ile doğrulanmalıdır."
    },
    {
      "requirement_id": "SW-002",
      "methods": [
        "Test"
      ],
      "rationale": "Rol tabanlı erişim kontrolünün ve yetkisiz isteklerde HTTP 403 yanıtının, farklı rollerle yapılan istekler üzerinden sistemin çalıştırılarak gözlemlenmesiyle doğrulanması gerekir."
    },
    {
      "requirement_id": "SW-003",
      "methods": [
        "Test"
      ],
      "rationale": "Hız sınırlama eşiğinin aşılması durumunda HTTP 429 yanıtı ve Retry-After başlığının, kontrollü istek yükü uygulanarak sistemin davranışının gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-004",
      "methods": [
        "Analiz"
      ],
      "rationale": "Belirli bir yük altında (2.000 istek/sn) 99. persentil gecikme metriklerinin istatistiksel olarak hesaplanması ve değerlendirilmesi gerektiği için analiz yöntemi uygundur."
    },
    {
      "requirement_id": "SW-005",
      "methods": [
        "Test"
      ],
      "rationale": "Arka uç servisin yanıt vermemesi senaryosunda ağ geçidinin isteği sonlandırıp HTTP 504 dönmesi, simüle edilmiş gecikme ile sistemin çalıştırılarak gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "SW-006",
      "methods": [
        "Test"
      ],
      "rationale": "Yapılandırma değişikliğinin yeniden başlatma gerektirmeden ve devam eden istekleri düşürmeden uygulanması, canlı sistem üzerinde değişiklik yapılarak ve istek akışı izlenerek test edilmelidir."
    },
    {
      "requirement_id": "SW-007",
      "methods": [
        "Test"
      ],
      "rationale": "İsteklerin işlenmesinin ardından günlük dosyasında veya sistemde beklenen alanların (izleme kimliği, süre vb.) mevcut olup olmadığı, istek gönderimi ve log kontrolü ile test edilebilir."
    },
    {
      "requirement_id": "SW-008",
      "methods": [
        "Analiz"
      ],
      "rationale": "Aylık kullanılabilirlik yüzdesinin (99.95%) hesaplanması, sistem çalışma süreleri ve kesinti süreleri verilerinin istatistiksel olarak analiz edilmesini gerektirir."
    }
  ]
}

{
  "decisions": [
    {
      "requirement_id": "KMU-001",
      "methods": [
        "Test"
      ],
      "rationale": "Sistemin e-Devlet entegrasyonu ile oturum açma işlevinin çalışıp çalışmadığı, gerçek bir kullanıcı senaryosu üzerinden sistemin çalıştırılması ve girdi verilerek gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-002",
      "methods": [
        "Test"
      ],
      "rationale": "15 dakikalık inaktivite süresinin sonunda oturumun sonlandırılması ve yönlendirme davranışının, zamanlayıcı senaryosu ile sistemin çalıştırılarak gözlemlenmesiyle doğrulanabilir."
    },
    {
      "requirement_id": "KMU-003",
      "methods": [
        "Test"
      ],
      "rationale": "Art arda 5 başarısız giriş denemesi sonrası hesap kilitlenmesi ve 30 dakikalık kilit süresinin, sisteme girdi verilerek ve sonuçların gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-004",
      "methods": [
        "Test"
      ],
      "rationale": "Dosya türü, boyut limiti (10 MB) ve adet limiti (5 dosya) kısıtlarının uygulanıp uygulanmadığı, farklı senaryolarla sistemin çalıştırılarak ve girdi verilerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-005",
      "methods": [
        "Test"
      ],
      "rationale": "Benzersiz takip numarası üretimi ve e-posta bildirimi işleminin, bir başvuru tamamlanarak sistemin çalıştırılması ve çıktıların gözlemlenmesiyle test edilebilir."
    },
    {
      "requirement_id": "KMU-006",
      "methods": [
        "Test"
      ],
      "rationale": "Taslak kaydetme ve 30 gün içinde kaldığı yerden devam etme işlevinin, sistemin çalıştırılarak ve zamanlama senaryoları ile gözlemlenerek doğrulanabilir."
    },
    {
      "requirement_id": "KMU-007",
      "methods": [
        "İnceleme"
      ],
      "rationale": "WCAG 2.1 AA uyumluluğunun, kullanıcı arayüzü kodunun, yapılandırmasının ve erişilebilirlik araçlarının çıktısının gözle denetlenerek (inceleme) doğrulanması gerekir."
    },
    {
      "requirement_id": "KMU-008",
      "methods": [
        "İnceleme"
      ],
      "rationale": "Verilerin yalnızca Türkiye sınırları içindeki sunucularda saklanmasının, altyapı yapılandırma belgeleri ve sunucu konum ayarlarının gözle denetlenerek (inceleme) doğrulanması gerekir."
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-KMU-007-01",
      "title": "WCAG 2.1 AA uyumlu otomatik erişilebilirlik denetimi",
      "covers": [
        "KMU-007"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "Sistem test ortamında çalışır durumda ve tarayıcı uyumluluk araçları yüklüdür.",
      "test_inputs": "Sistem ana sayfası ve temel başvuru formu URL'leri.",
      "assumptions": "Tarayıcı tabanlı bir otomatik erişilebilirlik denetleme aracı (ör. axe-core, Lighthouse) kullanılacaktır.",
      "steps": [
        {
          "no": 1,
          "action": "Otomatik erişilebilirlik denetleme aracının WCAG 2.1 AA profili ile sistem ana sayfası taranır.",
          "expected": "Rapor, WCAG 2.1 AA düzeyi için 'fail' veya 'critical' seviyesinde hata içermez."
        },
        {
          "no": 2,
          "action": "Aynı araç ile temel başvuru formu sayfası taranır.",
          "expected": "Form elemanları için WCAG 2.1 AA düzeyi 'fail' seviyesinde hata raporlanmaz."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-001",
      "title": "Macro-averaged F1 score verification on held-out set",
      "covers": [
        "AI-002"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. A held-out evaluation set with ground truth labels is available.",
      "test_inputs": "Held-out evaluation dataset with known ground truth labels.",
      "assumptions": "The evaluation script calculates the macro-averaged F1 score correctly according to standard definitions.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the held-out evaluation set to generate predictions for all documents.",
          "expected": "The system generates a prediction for every document in the evaluation set without errors."
        },
        {
          "no": 2,
          "action": "Calculate the macro-averaged F1 score by comparing the model's predictions with the ground truth labels.",
          "expected": "The calculated macro-averaged F1 score is at least 0.90."
        }
      ]
    },
    {
      "id": "TC-002",
      "title": "Recall difference between Turkish and English documents",
      "covers": [
        "AI-008"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The classification model is trained and ready for evaluation. The held-out evaluation set contains a sufficient number of documents labeled with both Turkish and English language metadata.",
      "test_inputs": "Held-out evaluation dataset containing documents explicitly tagged as Turkish and English.",
      "assumptions": "The evaluation set contains enough samples in both languages to provide statistically reliable recall estimates for the test.",
      "steps": [
        {
          "no": 1,
          "action": "Run the classification model on the subset of the held-out evaluation set containing only Turkish documents and calculate the recall for this subset.",
          "expected": "The recall value for Turkish documents is computed and recorded (R_TR)."
        },
        {
          "no": 2,
          "action": "Run the classification model on the subset of the held-out evaluation set containing only English documents and calculate the recall for this subset.",
          "expected": "The recall value for English documents is computed and recorded (R_EN)."
        },
        {
          "no": 3,
          "action": "Calculate the absolute difference between R_TR and R_EN and compare it to the 5 percentage point threshold.",
          "expected": "The absolute difference between the recall of Turkish and English documents is less than or equal to 5 percentage points."
        }
      ]
    }
  ]
}

{
  "test_cases": [
    {
      "id": "TC-01",
      "title": "Verify AES-256 encryption of stored casualty data",
      "covers": [
        "MED-006"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed on the tablet and at least one casualty record has been saved.",
      "test_inputs": "A known casualty record with unique identifiers.",
      "assumptions": "The tester has access to the device file system or forensic tools to inspect the raw storage blocks where the application data is persisted.",
      "steps": [
        {
          "no": 1,
          "action": "Create a new casualty record with a unique patient ID and vital signs in the application.",
          "expected": "The record is successfully saved and visible in the application interface."
        },
        {
          "no": 2,
          "action": "Inspect the raw storage area on the device where the application data is written (e.g., using a hex editor or forensic tool).",
          "expected": "The raw data is not readable as plain text; it appears as encrypted binary data."
        },
        {
          "no": 3,
          "action": "Verify the encryption algorithm configuration or key management logs (if accessible) or perform a cryptographic analysis of the ciphertext.",
          "expected": "The data is confirmed to be encrypted using AES-256."
        }
      ]
    },
    {
      "id": "TC-02",
      "title": "Verify battery life under defined usage profile for 8 hours",
      "covers": [
        "MED-008"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "The tablet is fully charged (100% battery). The 'defined usage profile' is documented and agreed upon by stakeholders.",
      "test_inputs": "Defined usage profile script (e.g., continuous data entry, screen on, specific brightness).",
      "assumptions": "The 'defined usage profile' includes specific parameters for screen brightness, network activity, and data entry rate. If not specified, assume standard field triage usage: screen at 50% brightness, Wi-Fi active, continuous input of casualty data every 30 seconds.",
      "steps": [
        {
          "no": 1,
          "action": "Start the tablet with 100% battery and begin the defined usage profile (simulating continuous triage data entry).",
          "expected": "The application is running and the battery level is at 100%."
        },
        {
          "no": 2,
          "action": "Continue the usage profile until 8 hours have elapsed.",
          "expected": "The tablet is still operational and the battery level is greater than 0%."
        },
        {
          "no": 3,
          "action": "Check the battery level indicator.",
          "expected": "The battery level is at or above the threshold that indicates the device has not shut down or entered critical low-power mode that prevents operation."
        }
      ]
    }
  ]
}

{
