{
  "test_cases": [
    {
      "id": "TC-1",
      "title": "Offline operation and local storage of 500 records",
      "covers": [
        "MED-004"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The application is installed and the device is connected to the server. The local database is empty.",
      "test_inputs": "",
      "assumptions": "The device's network interface can be disabled to simulate loss of connectivity.",
      "steps": [
        {
          "no": 1,
          "action": "Disable the device's network connectivity.",
          "expected": "The application remains open and responsive without crashing."
        },
        {
          "no": 2,
          "action": "Create a new casualty record with valid data.",
          "expected": "The record is saved successfully and appears in the local list."
        },
        {
          "no": 3,
          "action": "Create 499 additional casualty records with valid data.",
          "expected": "All 499 records are saved successfully and appear in the local list."
        },
        {
          "no": 4,
          "action": "Verify the total number of locally stored records.",
          "expected": "The local storage contains exactly 500 casualty records."
        }
      ]
    },
    {
      "id": "TC-2",
      "title": "Offline operation at storage boundary",
      "covers": [
        "MED-004"
      ],
      "type": "Sınır",
      "priority": "Orta",
      "preconditions": "The device is offline. The local database already contains 500 casualty records.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Attempt to create a 501st casualty record.",
          "expected": "The application allows the creation of the record or indicates the limit; if allowed, the record is stored locally."
        },
        {
          "no": 2,
          "action": "Verify the local storage capacity handling.",
          "expected": "The application remains functional and does not corrupt existing data."
        }
      ]
    },
    {
      "id": "TC-3",
      "title": "Synchronization after connectivity restoration",
      "covers": [
        "MED-005"
      ],
      "type": "Normal",
      "priority": "Yüksek",
      "preconditions": "The device was offline and has 10 unsynchronized local records. The server has no conflicting records for these IDs.",
      "test_inputs": "",
      "assumptions": "",
      "steps": [
        {
          "no": 1,
          "action": "Re-enable the device's network connectivity.",
          "expected": "The application detects the connection and initiates synchronization."
        },
        {
          "no": 2,
          "action": "Wait for the synchronization process to complete.",
          "expected": "The 10 local records are transmitted to the server and marked as synchronized."
        },
        {
          "no": 3,
          "action": "Verify the server database.",
          "expected": "The server contains the 10 records with identical data to the local versions."
        }
      ]
    },
    {
      "id": "TC-4",
      "title": "Conflict resolution during synchronization",
      "covers": [
        "MED-005"
      ],
      "type": "Hata",
      "priority": "Yüksek",
      "preconditions": "A casualty record (ID: C-001) exists on both the local device and the server. The local version has been modified while offline. The server version has been modified by another user.",
      "test_inputs": "Local modification: Age changed to 30. Server modification: Age changed to 35.",
      "assumptions": "",
      "steps": [
